#include <CGAL/Exact_predicates_inexact_constructions_kernel.h>
#include <vector>
#include <iostream>
#include <algorithm>

typedef CGAL::Exact_predicates_inexact_constructions_kernel K;
typedef K::Point_2 Point_2;

Point_2 leftmost_point(const std::vector<Point_2>& points) {
    if (points.empty()) {
        return Point_2(0, 0);
    }
    auto it = std::min_element(points.begin(), points.end(), [](const Point_2& a, const Point_2& b) {
        if (a.x() != b.x()) {
            return a.x() < b.x();
        }
        return a.y() < b.y();
    });
    return *it;
}

int main() {
    std::vector<Point_2> pts = { Point_2(2, 2), Point_2(1, 5), Point_2(1, 2), Point_2(3, 1) };
    Point_2 res = leftmost_point(pts);
    std::cout << "Result: " << res.x() << ", " << res.y() << std::endl;
    // Expected: 1, 2
    return 0;
}

